<section class="container standard-page admin-page"><div class="page-title"><span class="eyebrow">ZORA MANAGEMENT</span><h1>Kelola produk</h1><p>Tambah produk baru atau arsipkan produk yang tidak lagi dijual.</p></div><div class="admin-product-layout"><form class="form-card" method="post" action="<?= base_url('admin/products/create') ?>"><?= csrf_field() ?><h3>Tambah produk</h3><label>Nama produk<input name="name" required></label><label>SKU<input name="sku" required></label><label>Kategori<select name="category_id"><option value="">Tanpa kategori</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Harga<input type="number" name="price" min="1" required></label><label>Harga pembanding<input type="number" name="compare_at_price" min="0"></label><label>Stok<input type="number" name="stock" min="0" value="0"></label><label>Warna<input name="color"></label></div><label>URL gambar<input type="url" name="image_url" placeholder="https://..."></label><label>Tag<input name="tag" placeholder="NEW / POPULAR"></label><label>Deskripsi<textarea name="description" rows="3"></textarea></label><label class="checkbox-label"><input type="checkbox" name="is_featured" value="1"> Tampilkan sebagai produk pilihan</label><button class="btn-zora w-100">Simpan produk →</button></form><div class="admin-product-list"><h3>Daftar produk</h3><div class="table-responsive"><table class="table zora-table"><thead><tr><th>Produk</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><small class="d-block text-muted"><?= e($p['sku']) ?></small></td><td><?= rupiah($p['price']) ?></td><td><?= (int)$p['stock'] ?></td><td><?php if($p['status']==='active'): ?><form method="post" action="<?= base_url('admin/products/delete') ?>" onsubmit="return confirm('Arsipkan produk ini?')"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><button class="remove-button">Arsipkan</button></form><?php else: ?><span class="text-muted">Archived</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section>
